//! Canonical INPUT constraint flags preserve native validation and editor state.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form method=post action=https://input-constraint-flags.test/send><input id=area name=q required><input id=input type=submit name=i value=I><button id=button type=submit name=b value=B>Send</button></form><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://input-constraint-flags.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn input_constraint_flags_required_canonical_hook_free_truthiness_and_presence(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"for(var id of ['input']){var x=document.getElementById(id),P=id==='input'?HTMLInputElement.prototype:HTMLButtonElement.prototype,a=Object.getOwnPropertyDescriptor(P,'required');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get required'||a.set.name!=='set required'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'required')||x.required!==false)throw 'canonical';var calls=0,author={toString:function(){calls++;throw 'conversion';},valueOf:function(){calls++;throw 'conversion';}};for(var value of [true,1,-1,Infinity,'false',[],{},new Boolean(false),Symbol('bool'),BigInt(1),author]){a.set.call(x,value);if(x.required!==true||x.getAttributeNS(null,'required')!==''||calls)throw 'true';}for(var value of [false,0,-0,NaN,'',null,undefined,BigInt(0)]){a.set.call(x,value);if(x.required!==false||x.hasAttribute('required')||calls)throw 'false';}a.set.call(x);if(x.required!==false||calls)throw 'missing argument';}");}
#[test]
fn input_constraint_flags_required_inert_exact_namespace_raw_presence_and_copy(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var tag of ['input']){var x=(new Document()).createElementNS('http://www.w3.org/1999/xhtml',tag);x.setAttributeNS('urn:foreign','required','foreign');x.setAttributeNS(null,'REQUIRED','upper');if(x.required!==false)throw 'namespace';x.setAttributeNS(null,'required','\ud800');if(x.required!==true)throw 'raw presence';var a=x.getAttributeNodeNS(null,'required'),copy=x.cloneNode(false);copy.required=false;if(copy.required!==false||x.required!==true||a.value!=='\ud800'||copy.getAttributeNS('urn:foreign','required')!=='foreign')throw 'copy';x.required=true;if(x.getAttributeNodeNS(null,'required')!==a||a.value!=='')throw 'identity';}"#);}
#[test]
fn input_constraint_flags_read_only_canonical_hook_free_truthiness_and_presence(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"for(var id of ['input']){var x=document.getElementById(id),P=id==='input'?HTMLInputElement.prototype:HTMLButtonElement.prototype,a=Object.getOwnPropertyDescriptor(P,'readOnly');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get readOnly'||a.set.name!=='set readOnly'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'readOnly')||x.readOnly!==false)throw 'canonical';var calls=0,author={toString:function(){calls++;throw 'conversion';},valueOf:function(){calls++;throw 'conversion';}};for(var value of [true,1,-1,Infinity,'false',[],{},new Boolean(false),Symbol('bool'),BigInt(1),author]){a.set.call(x,value);if(x.readOnly!==true||x.getAttributeNS(null,'readonly')!==''||calls)throw 'true';}for(var value of [false,0,-0,NaN,'',null,undefined,BigInt(0)]){a.set.call(x,value);if(x.readOnly!==false||x.hasAttribute('readonly')||calls)throw 'false';}a.set.call(x);if(x.readOnly!==false||calls)throw 'missing argument';}");}
#[test]
fn input_constraint_flags_read_only_inert_exact_namespace_raw_presence_and_copy(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var tag of ['input']){var x=(new Document()).createElementNS('http://www.w3.org/1999/xhtml',tag);x.setAttributeNS('urn:foreign','readonly','foreign');x.setAttributeNS(null,'READONLY','upper');if(x.readOnly!==false)throw 'namespace';x.setAttributeNS(null,'readonly','\ud800');if(x.readOnly!==true)throw 'raw presence';var a=x.getAttributeNodeNS(null,'readonly'),copy=x.cloneNode(false);copy.readOnly=false;if(copy.readOnly!==false||x.readOnly!==true||a.value!=='\ud800'||copy.getAttributeNS('urn:foreign','readonly')!=='foreign')throw 'copy';x.readOnly=true;if(x.getAttributeNodeNS(null,'readonly')!==a||a.value!=='')throw 'identity';}"#);}
#[test]
fn input_constraint_flags_required_brands_saved_prototype_and_native_observation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"for(var id of ['input']){var x=document.getElementById(id),other=document.getElementById(id==='input'?'button':'input'),P=id==='input'?HTMLInputElement.prototype:HTMLButtonElement.prototype,a=Object.getOwnPropertyDescriptor(P,'required');for(var bad of [{},document,document.body,document.getElementById('form'),other,Object.create(P)]){try{a.set.call(bad,true);throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}x.setAttribute('required','legacy');var old=x.getAttributeNodeNS(null,'required'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.required=false;var records=watch.takeRecords();if(x.required!==false||old.ownerElement!==null||old.value!=='legacy'||records.length!==1||records[0].oldValue!=='legacy'||records[0].attributeName!=='required')throw 'remove observation';var calls=0;x.required={toString:function(){calls++;throw 'coercion';},valueOf:function(){calls++;throw 'coercion';}};records=watch.takeRecords();if(calls||x.required!==true||x.getAttributeNS(null,'required')!==''||records.length!==1||records[0].oldValue!==null)throw 'hook free observation';watch.disconnect();Object.defineProperty(P,'required',{get:function(){return 'author';},configurable:true});a.set.call(x,false);if(x.required!=='author'||a.get.call(x)!==false)throw 'saved authority';Object.defineProperty(P,'required',a);}");}
#[test]
fn input_constraint_flags_required_captured_origin_denies_then_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var input=document.getElementById('input'),button=document.getElementById('input'),a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLInputElement.prototype,'required'),b=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLInputElement.prototype,'required');if(a.get.call(input)!==false||b.get.call(button)!==false)throw 'same origin';");p.set_location(&crate::navigation::address("https://foreign-input-constraint-flags.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);for code in ["a.get.call(input);","b.get.call(button);","a.set.call(input,true);","b.set.call(button,true);"]{p.begin_job();let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);}p.set_location(&crate::navigation::address("https://input-constraint-flags.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"a.set.call(input,true);b.set.call(button,true);if(input.required!==true||button.required!==true)throw 'fresh recovery';");}
#[test]
fn input_constraint_flags_required_bounded_atomic_refusal_and_zero_copy_getter(){for id in ["input"]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();let Value::Host(object)=p.runtime.execute(&format!("var x=document.getElementById('{id}');x;"),&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("submitter")};let before=format!("{:?}",d.nodes);let retained=p.state.retained_limit;let capture=(p.state.retained,p.state.dom_commits);p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if id=="input"{bridge.input_required_set(object,&Value::Bool(true))}else{bridge.input_required_set(object,&Value::Bool(true))};assert!(result.is_err(),"id {id} mode {mode}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),capture);p.state.retained_limit=retained;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.required=true;if(x.required!==true)throw 'fresh recovery';");}for expired in [false,true]{let(mut d,mut f,mut p)=fixture();let Value::Host(object)=p.runtime.execute(&format!("document.getElementById('{id}');"),&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("submitter")};p.begin_job();if expired{p.state.execution_deadline=Some(Instant::now());}else{p.state.host_work=0;}let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if id=="input"{bridge.input_required_get(object)}else{bridge.input_required_get(object)};assert!(result.is_err());p.state.execution_deadline=None;p.begin_job();p.state.copy_work=0;let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if id=="input"{bridge.input_required_get(object)}else{bridge.input_required_get(object)};assert!(matches!(result,Ok(Value::Bool(false))));}}}
#[test]
fn input_constraint_flags_required_attribute_writers_preserve_dirty_editor(){for id in ["input"]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('{id}'),editor=document.getElementById('area');editor.value='Edited';x.required=true;var attribute=x.getAttributeNodeNS(null,'required'),watch=new MutationObserver(function(){{}});watch.observe(x,{{attributes:true,attributeOldValue:true}});"));let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for code in ["x.setAttribute('required','false');","x.setAttributeNS(null,'required','false');","attribute.value='false';","attribute.nodeValue='false';","attribute.textContent='false';"]{p.begin_job();run(&mut d,&mut f,&mut p,"x.required=true;watch.takeRecords();");run(&mut d,&mut f,&mut p,code);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.required!==true||x.getAttributeNodeNS(null,'required')!==attribute||records.length!==1||records[0].oldValue!==''||records[0].attributeName!=='required'||editor.value!=='Edited')throw 'attribute observation';");let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value,c.required),(3,1,2,true,true));}run(&mut d,&mut f,&mut p,r#"var replacement=document.createAttribute('required');replacement.value='\ud800';x.setAttributeNodeNS(replacement);if(x.required!==true||attribute.ownerElement!==null||replacement.ownerElement!==x)throw 'raw replacement';x.required=false;if(x.required!==false||replacement.ownerElement!==null)throw 'remove';"#);}}

