fn input_constraint_flags_read_only_brands_saved_prototype_and_native_observation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"for(var id of ['input']){var x=document.getElementById(id),other=document.getElementById(id==='input'?'button':'input'),P=id==='input'?HTMLInputElement.prototype:HTMLButtonElement.prototype,a=Object.getOwnPropertyDescriptor(P,'readOnly');for(var bad of [{},document,document.body,document.getElementById('form'),other,Object.create(P)]){try{a.set.call(bad,true);throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}x.setAttribute('readonly','legacy');var old=x.getAttributeNodeNS(null,'readonly'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.readOnly=false;var records=watch.takeRecords();if(x.readOnly!==false||old.ownerElement!==null||old.value!=='legacy'||records.length!==1||records[0].oldValue!=='legacy'||records[0].attributeName!=='readonly')throw 'remove observation';var calls=0;x.readOnly={toString:function(){calls++;throw 'coercion';},valueOf:function(){calls++;throw 'coercion';}};records=watch.takeRecords();if(calls||x.readOnly!==true||x.getAttributeNS(null,'readonly')!==''||records.length!==1||records[0].oldValue!==null)throw 'hook free observation';watch.disconnect();Object.defineProperty(P,'readOnly',{get:function(){return 'author';},configurable:true});a.set.call(x,false);if(x.readOnly!=='author'||a.get.call(x)!==false)throw 'saved authority';Object.defineProperty(P,'readOnly',a);}");}
