fn input_constraint_flags_read_only_bounded_atomic_refusal_and_zero_copy_getter(){for id in ["input"]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();let Value::Host(object)=p.runtime.execute(&format!("var x=document.getElementById('{id}');x;"),&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("submitter")};let before=format!("{:?}",d.nodes);let retained=p.state.retained_limit;let capture=(p.state.retained,p.state.dom_commits);p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if id=="input"{bridge.input_read_only_set(object,&Value::Bool(true))}else{bridge.input_read_only_set(object,&Value::Bool(true))};assert!(result.is_err(),"id {id} mode {mode}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),capture);p.state.retained_limit=retained;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.readOnly=true;if(x.readOnly!==true)throw 'fresh recovery';");}for expired in [false,true]{let(mut d,mut f,mut p)=fixture();let Value::Host(object)=p.runtime.execute(&format!("document.getElementById('{id}');"),&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("submitter")};p.begin_job();if expired{p.state.execution_deadline=Some(Instant::now());}else{p.state.host_work=0;}let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if id=="input"{bridge.input_read_only_get(object)}else{bridge.input_read_only_get(object)};assert!(result.is_err());p.state.execution_deadline=None;p.begin_job();p.state.copy_work=0;let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if id=="input"{bridge.input_read_only_get(object)}else{bridge.input_read_only_get(object)};assert!(matches!(result,Ok(Value::Bool(false))));}}}
