fn input_constraint_flags_read_only_attribute_writers_preserve_dirty_editor(){for id in ["input"]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('{id}'),editor=document.getElementById('area');editor.value='Edited';x.readOnly=true;var attribute=x.getAttributeNodeNS(null,'readonly'),watch=new MutationObserver(function(){{}});watch.observe(x,{{attributes:true,attributeOldValue:true}});"));let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for code in ["x.setAttribute('readonly','false');","x.setAttributeNS(null,'readonly','false');","attribute.value='false';","attribute.nodeValue='false';","attribute.textContent='false';"]{p.begin_job();run(&mut d,&mut f,&mut p,"x.readOnly=true;watch.takeRecords();");run(&mut d,&mut f,&mut p,code);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.readOnly!==true||x.getAttributeNodeNS(null,'readonly')!==attribute||records.length!==1||records[0].oldValue!==''||records[0].attributeName!=='readonly'||editor.value!=='Edited')throw 'attribute observation';");let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value,c.required),(3,1,2,true,true));}run(&mut d,&mut f,&mut p,r#"var replacement=document.createAttribute('readonly');replacement.value='\ud800';x.setAttributeNodeNS(replacement);if(x.readOnly!==true||attribute.ownerElement!==null||replacement.ownerElement!==x)throw 'raw replacement';x.readOnly=false;if(x.readOnly!==false||replacement.ownerElement!==null)throw 'remove';"#);}}


#[test]
fn input_constraint_flags_native_required_readonly_exemption_script_values_and_recovery(){let(mut d,mut f,mut p)=fixture();let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();let area=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("area")).unwrap();let location=crate::navigation::address("https://input-constraint-flags.test/source",&crate::navigation::Location::home()).unwrap();assert!(f.submit_request(&d,owner,None,&location,&location).is_err());run(&mut d,&mut f,&mut p,"var a=document.getElementById('area');a.readOnly=true;if(!a.required||!a.readOnly||a.value!=='')throw 'readonly required presence';");assert!(f.controls[&area].required&&f.controls[&area].readonly);let request=f.submit_request(&d,owner,None,&location,&location).unwrap();let crate::http::Request::FormPost{body,..}=request.request else{panic!("POST")};assert_eq!(body,b"q=");run(&mut d,&mut f,&mut p,"a.value='Edited';if(!a.readOnly||a.value!=='Edited'||a.defaultValue!=='')throw 'script readonly value';a.readOnly=false;a.value='';");assert!(f.controls[&area].dirty_value);assert!(f.submit_request(&d,owner,None,&location,&location).is_err());run(&mut d,&mut f,&mut p,"a.required=false;");assert!(f.submit_request(&d,owner,None,&location,&location).is_ok());run(&mut d,&mut f,&mut p,"a.required=true;a.value='Seed';");let request=f.submit_request(&d,owner,None,&location,&location).unwrap();let crate::http::Request::FormPost{body,..}=request.request else{panic!("POST")};assert_eq!(body,b"q=Seed");assert!(f.controls[&area].required&&!f.controls[&area].readonly);}
#[test]
fn input_constraint_flags_native_checkbox_and_radio_required_ignore_readonly(){let mut d=crate::html::parse("<form id=form method=post action=https://input-constraint-flags.test/submit><input id=check type=checkbox name=c value=C><input id=one type=radio name=r value=One><input id=two type=radio name=r value=Two></form>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();let location=crate::navigation::address("https://input-constraint-flags.test/source",&crate::navigation::Location::home()).unwrap();run(&mut d,&mut f,&mut p,"var c=document.getElementById('check'),one=document.getElementById('one'),two=document.getElementById('two');c.required=true;c.readOnly=true;if(!c.required||!c.readOnly)throw 'checkbox presence';");assert!(f.submit_request(&d,owner,None,&location,&location).is_err());run(&mut d,&mut f,&mut p,"c.checked=true;");assert!(f.submit_request(&d,owner,None,&location,&location).is_ok());run(&mut d,&mut f,&mut p,"one.required=true;one.readOnly=true;");assert!(f.submit_request(&d,owner,None,&location,&location).is_err());run(&mut d,&mut f,&mut p,"two.checked=true;");let request=f.submit_request(&d,owner,None,&location,&location).unwrap();let crate::http::Request::FormPost{body,..}=request.request else{panic!("POST")};assert_eq!(body,b"c=C&r=Two");run(&mut d,&mut f,&mut p,"c.required=false;one.required=false;c.checked=false;two.checked=false;if(c.required||one.required||!c.readOnly||!one.readOnly)throw 'required removal preserves readonly';");assert!(f.submit_request(&d,owner,None,&location,&location).is_ok());}
